"""Sort the given models based on their dependencies. It uses a depth-first search to sort the models based on their dependencies and returns the sorted list of models.

:param models: List. A list of model instances to be sorted.
:return: List. The sorted list of model instances based on their dependencies.
"""
# Create a dictionary of models to their dependent models.
model_dependencies = {}
for model in models:
    model_dependencies[model] = set(getattr(model, "depends_on", []))

# Create a dictionary of models to their dependents.
model_dependents = {}
for model in models:
    for dep in model_dependencies.keys():
        if model in model_dependencies[dep]:
            model_dependents.setdefault(model, set()).add(dep)

# Find the models that are not dependent on any other model.
roots = [model for model in models if model not in model_dependents]

# Find the models that are not dependent on any other model.
sorted_models = []
while roots:
    root = roots.pop()
    sorted_models.append(root)
    for dependent_model in model_dependents.pop(root, []):
        model_dependencies.pop(dependent_model)
        if not model_dependencies[dependent_model]:
            roots.append(dependent_model)

# If there are models left over, there must be a circular dependency.
if model_dependencies:
    raise RuntimeError("Circular dependency in models: %s" % ", ".join(repr(model) for model in model_dependencies.keys()))

return sorted_models

