    ].add(
        middleware
    )

def _inspect_middleware_tree(middleware, middleware_type, parent_middleware_type):
    """Inspects a middleware component and adds it to the appropriate data structures.

    :param middleware: Union[falcon.Middleware, falcon.middleware.ASGIMiddleware]. The middleware component to inspect.
    :param middleware_type: str. The type of middleware component.
    :param parent_middleware_type: str. The type of the parent middleware component.
    """
    middleware_id = id(middleware)
    middleware_tree[middleware_type][middleware_id] = []
    middleware_tree[middleware_type][middleware_id].append(middleware)
    middleware_tree[parent_middleware_type][middleware_id].append(middleware)
    middleware_tree[parent_middleware_type][middleware.__class__.__name__][middleware_id].append(
        middleware
    )
    middleware_tree[parent_middleware_type][middleware.__class__.__name__][middleware_type][
        middleware_id
    ].append(middleware)
