"""This function takes in a text and a list of entities and returns the inner text that is surrounded by the given entities. It iterates through each entity, extracts the corresponding inner text, and appends it to the result list.

:param text: String. The original text.
:param entities: List of entities. The entity or entities that must be matched.
:return: List of strings. A list of the text surrounded by the entities.
"""
if not entities:
    return [text]
if not text:
    return []
if not isinstance(entities, list):
    entities = [entities]
result = []
for e in entities:
    if e.offset in (0, len(text) - 1):
        continue
    if isinstance(e, types.MessageEntityMentionName):
        result.append(text[e.offset + 1: e.offset + e.length])
    elif isinstance(e, (types.MessageEntityBold, types.MessageEntityItalic)):
        result.append(text[e.offset + 1: e.offset + e.length - 1])
    elif isinstance(e, types.MessageEntityCode):
        result.append(text[e.offset + 1: e.offset + e.length - 1])
    elif isinstance (e, types.MessageEntityPre):
        result.append(text[e.offset + 1: e.offset + e.length - 1])
    elif issubclass(e.__class__, types.MessageEntityTextUrl):
        result.append(text[e.offset + 1: e.offset + e.length - 1])
    elif isclass(e):
        result.append(text[e.offset: e.offset + e.length])
    else:
        result.append(text[e.offset: e.offset + e.length])
return result

