"""This function creates a DropConstraintOp instance based on the given constraint. It determines the type of constraint and creates the instance with the corresponding parameters.

:param cls: type. The DropConstraintOp class.
:param constraint: Constraint. The constraint object to create the DropConstraintOp instance from.
:return: DropConstraintOp. The created DropConstraintOp instance.
"""
if isinstance(constraint, CheckConstraint):
    return cls(constraint.name, "check", constraint.table.name, schema=constraint.schema)
elif isinstance(constraint, UniqueConstraint):
    return cls(
        constraint.name,
        "unique",
        constraint.table.name,
        constraint.columns.keys(),
        schema=constraint.schema,
    )
elif isinstance(constraint, ForeignKeyConstraint):
    return cls(
        constraint.name,
        "foreignkey",
        constraint.table.name,
        constraint.columns.keys(),
        constraint.referred_table.name,
        constraint.referred_columns.keys(),
        schema=constraint.schema,
    )
else:
    raise ValueError(f"Unknown constraint type: {constraint!r}")

"""This function checks if the provided (epsilon, delta) values can be spent without exceeding the budget ceiling of the BudgetAccountant instance. It performs various checks and calculations to determine if the budget can be spent or if a budget error should be raised "Privacy spend of ({epsilon},{delta}) not permissible; will exceed remaining privacy budget. Use {class name}.{method for remaining budget}() to check remaining budget."

:param self: BudgetAccountant. An instance of the BudgetAccountant class.
:param epsilon: float. The epsilon budget spend to check.
:param delta: float. The delta budget spend to check.
:return: bool. True if the budget can be spent.
"""
if not isinstance(epsilon, float) or not isinstance(delta, float):
    raise TypeError(
        "Epsilon and delta must be float values. "
        + f"Epsilon is {type(epsilon)}, and delta is {type(delta)}."
    )

if epsilon < 0 or delta < 0:
    raise ValueError(
        "Epsilon and delta must be non-negative. "
        + f"Epsilon is {epsilon}, and delta is {delta}."
    )

if epsilon == 0.0 and delta == 0.0:
    raise ValueError("Epsilon and delta cannot both be zero.")

if epsilon == float("inf") or delta == float("inf"):
    raise ValueError("Epsilon and delta must be finite.")

if self.total_epsilon is None or self.total_delta is None:
    raise BudgetError(
        "Cannot spend budget without first setting the total budget ceiling. "
        + f"Use {self.__class__.__name__}.{self._set_total_budget.__name__}() to set the total budget ceiling."
    )

if self.total_epsilon < 0.0 or self.total_delta < 0.0:
    raise BudgetError(
        "Total epsilon and delta must be non-negative. "
        + f"Total epsilon is {self.total_epsilon}, and total delta is {self.total_delta}."
    )

if self.total_epsilon == 0.0 and self.total_delta == 0.0:
    raise BudgetError("Total epsilon and delta cannot both be zero.")

if self.total_epsilon == float("inf") or self.total_delta == float("inf"):
    raise BudgetError("Total epsilon and delta must be finite.")

if epsilon > self.total_epsilon:
    raise BudgetError(
        f"Epsilon ({epsilon}) cannot be greater than total epsilon ({self.total_epsilon})."
    )

if delta > self.total_delta:
    raise BudgetError(
        f"Delta ({delta}) cannot be greater than total delta ({self.total_delta})."
    )

if self.epsilon_spent + epsilon > self.total_epsilon:
    raise BudgetError(
        f"Epsilon ({self.epsilon_spent + epsilon}) cannot be greater than total epsilon ({self.total_epsilon})."
    )

if self.delta_spent + delta > self.total_delta:
    raise BudgetError(
        f"Delta ({self.delta_spent + delta}) cannot be greater than total delta ({self.total_delta})."
    )

return True

"""This function normalizes the search criteria by converting them into a standardized format. It handles different types of criteria and converts them accordingly including "int, str, datatime, list, tuple, bytes". If no criteria are specified, it raises the corresponding error. If no character set is specified, it defaults to "us-ascii".

:param criteria: The search criteria to be normalized. It can be a string, bytes, list, tuple, int, datetime, or date.
:param charset: The character set to be used for encoding. Defaults to "us-ascii" if not specified.
:return: A list of normalized search criteria.
"""
if not criteria:
    raise exceptions.IllegalArgumentError("'criteria' must be specified")

if isinstance(criteria, (str, bytes)):
    return [to_bytes(criteria, charset)]

if isinstance(criteria, (list, tuple)):
    return [to_bytes(c, charset) for c in criteria]

if isinstance(criteria, int):
    return [to_bytes(str(criteria), charset)]

if isinstance(criteria, (datetime.datetime, datetime.date)):
    return [to_bytes(criteria.strftime("%d-%b-%Y"), charset)]

raise exceptions.IllegalArgumentError(
    "'criteria' must be a string, bytes, list, tuple, int, datetime, or date"
)

"""This function returns a string representation of the StepFailedException instance: '{class name}({", "-separated list of fields: {field name}={field value}})'.

:param self: StepFailedException. An instance of the StepFailedException class.
:return: str. The string representation of the StepFailedException instance.
"""
return "{}({})".format(
    self.__class__.__name__,
    ", ".join(
        "{}={}".format(field, value)
        for field, value in sorted(self.__dict__.items())
    ),
)

"""This function combines multiple path sequences into a single list. It resolves `~` (home dir) and environment variables, and expands globs that refer to the local filesystem. It can take single strings as well as lists.

:param path_seqs: Variable number of sequences. The path sequences to be combined.
:return: List. The combined list of paths after resolving `~`, environment variables, and expanding globs.
"""
paths = []
for path_seq in path_seqs:
    if isinstance(path_seq, str):
        paths.extend(glob.glob(path_seq))
    else:
        paths.extend(path_seq)

return [
    os.path.realpath(os.path.expanduser(str(path)))
    for path in paths
    if filter_path(path)
]

"""This function takes in a URL, pathname to local or network file, or string as input and returns a stream object. It provides a uniform way to handle different types of input sources. The returned object has standard read methods (read, readline, readlines) and should be closed using the .close() method when no longer needed.

:param url_file_stream_or_string: The input source, which can be a URL, filename, or string.
:param etag: The value of the If-None-Match request header. Defaults to None.
:param modified: The value of the If-Modified-Since request header. Can be a tuple of 9 integers or a date string. Defaults to None.
:param agent: The value of the User-Agent request header. Defaults to None.
:param referrer: The value of the Referer request header. Defaults to None.
:param handlers: A list of handlers used to build a urllib2 opener. Defaults to None.
:param request_headers: A dictionary of HTTP request headers that override the values generated by FeedParser. Defaults to None.
:param result: A placeholder for the result. Defaults to None.
:return: A bytes object representing the stream.
"""
if isinstance(url_file_stream_or_string, _string_types):
    if url_file_stream_or_string.startswith("file://"):
        url_file_stream_or_string = url_file_stream_or_string[7:]
    if os.path.isfile(url_file_stream_or_string):
        return open(url_file_stream_or_string, "rb")
    else:
        return urlopen(
            Request(
                url_file_stream_or_string,
                headers=request_headers,
                unverifiable=True,
                **{
                    "agent": agent,
                    "referrer": referrer,
                    "etag": etag,
                    "modified": modified,
                }
            ),
            data=None,
            timeout=120,
            handlers=handlers,
        )
elif isinstance(url_file_stream_or_string, _file_types):
    return url_file_stream_or_string
elif hasattr(url_file_stream_or_string, "read"):
    return url_file_stream_or_string
elif isinstance(url_file_stream_or_string, _string_or_bytes_types):
    return io.BytesIO(url_file_stream_or_string)
else:
    raise ValueError("Unable to parse input source: %s" % url_file_stream_or_string)

"""This function compares a database schema to the schema given in a MetaData instance. It uses a MigrationContext object to provide database connectivity and optional comparison functions for datatypes and server defaults. The function returns a list of "diff" directives, each representing individual differences between the two schemas.

:param context: MigrationContext. An instance of the MigrationContext class that provides database connectivity and comparison functions.
:param metadata: MetaData. An instance of the MetaData class that represents the database schema to compare against.
:return: Any. The return format is a list of "diff" directives representing the differences between the two schemas.
"""

autogen_context = AutogenContext(context, metadata=metadata)
autogen_context.run_filters(
    lambda opt: opt._get_context_opts().get("compare_server_default_filters")
)

with context.begin_transaction():
    inspector = autogen_context.inspector
    mdata_schema_obj = metadata.schema
    mdata_schema = None if not mdata_schema_obj else mdata_schema_obj.strip()
    conn_schema = inspector.schema

    # for the "compare" api we want to use the dialect
    # specific identifier prep method, so we go out of our
    # way to have the schema_names() method format names
    # the way the dialect would.
    #
    # for the "render_item" api we just use native str().

    if mdata_schema is not None:
        to_compare = [mdata_schema]
    else:
        to_compare = inspector.get_schema_names()

    for schema in to_compare:
        if mdata_schema is None and schema == conn_schema:
            schema_names = [schema]
        else:
            schema_names = [
                compat_util.adapt_identifier_option_value(
                    context.dialect, schema
                )
            ]

        for sname in schema_names:
            # tables
            for tname in sorted(
                chain(
                    *[
                        inspector.get_table_names(schema=sname),
                        inspector.get_temp_table_names(schema=sname),
                    ]
                ):
                tname = compat_util.adapt_identifier_option_value(
                    context.dialect, tname
                )
                full_tname = "%s.%s" % (sname, tname)
                if full_tname in context.run_filters(
                    "table", full_tname, tname, sname, metadata
                ):
                    continue

                diffs = autogen_context.metadata_diff_two_objects(
                    schema=sname,
                    tname=tname,
                    obj1=None,
                    obj2=inspector.get_table_definition(
                        table_name=tname, schema=sname
                    ),
                )
                if diffs:
                    yield Diff(
                        tname,
                        sname,
                        diffs,
                        obj1=None,
                        obj2=inspector.get_table_definition(
                            table_name=tname, schema=sname
                        ),
                    )

            # views
            for vname in sorted(
                chain(
                    *[
                        inspector.get_view_names(schema=sname),
                        inspector.get_temp_view_names(schema=sname),
                    ]
                ):
                vname = compat_util.adapt_identifier_option_value(
                    context.dialect, vname
                )
                full_vname = "%s.%s" % (sname, vname)
                if full_vname in context.run_filters(
                    "view", full_vname, vname, sname, metadata
                ):
                    continue

                diffs = autogen_context.metadata_diff_two__objects(
                    schema=sname,
                    tname=vname,
                    obj1=None,
                    obj2=inspector.get_view_definition(
                        view_name=vname, schema=sname
                    ),
                )
                if diffs:
                    yield Diff(
                        vname,
                        sname,
                        diffs,
                        obj1=None,
                        obj2=inspector._inspect_view_definition(
                            view_name=vname, schema=sname
                        ),
                    )

            # enums
            for enum in sorted(
                chain(
                    *[
                        inspector.get_enums(schema=sname),
                        inspector.get_temp_enums(schema=sname),
                    ]
                ):
                enum = compat_util.adapt_identifier_option_value(
                    context.dialect, enum
                )
                full_enum = "%s.%s" % (sname, enum)
                if full_enum in context.run_filters(
                    "enum", full_enum, enum, sname, metadata
                ):
                    continue

                diffs = autogen_context.metadata_diff_two_object(
                    schema=sname,
                    tname=enum,
                    obj1=None,
                    obj2=inspector.get_enum(enum_name=enum, schema=sname),
                )
                if diffs:
