"""This function retrieves the latest response from a JsonRpcClient instance. It checks the response map for the given request_id and owner_uri in priority order: Response, Event, Exception. If a response is found, it is returned. If no response is found, an exception is raised if available. If no exception is available, None is returned.

:param self: JsonRpcClient. An instance of the JsonRpcClient class.
:param request_id: int. The ID of the request to retrieve the response for. Defaults to 0.
:param owner_uri: int. The URI of the owner to retrieve the response for. Defaults to 0.
:return: The latest response from the JsonRpcClient instance, or None if no response is available.
"""
response = None
try:
    response = self.response_map[request_id][owner_uri]
except KeyError:
    pass
if response is None:
    try:
        response = self.event_map[request_id][owner_uri]
    except KeyError:
        pass
if response is None:
    try:
        response = self.exception_map[request_id][owner_uri]
    except KeyError:
        pass
return response

"""This function summarizes a given series of data based on the specified configuration and data type.

:param self: BaseSummarizer. An instance of the BaseSummarizer class.
:param config: Settings. The configuration settings for the summarization process.
:param series: pd.Series. The series of data to be summarized.
:param dtype: Type[VisionsBaseType]. The data type of the series.
:return: dict. The summary of the data.
"""
summary = {}
if config.summary.get("count"):
    summary["count"] = series.count()

if config.summary.get("unique"):
    summary["unique"] = series.nunique()

if config.summary.get("top"):
    summary["top"] = series.value_counts().index[0]

if config.summary.get("freq"):
    summary["freq"] = series.value_counts().iloc[0]

if config.summary.get("mean"):
    summary["mean"] = series.mean()

if config.summary.get("min"):
    summary["min"] = series.min()

if config.summary.get("max"):
    summary["max"] = series.max()

if config.summary.get("sum"):
    summary["sum"] = series.sum()

if config.summary.get("std"):
    summary["std"] = series.std()

if config.summary.get("variance"):
    summary["variance"] = series.var()

if config.summary.get("median"):
    summary["median"] = series.median()

if config.summary.get("quantile"):
    summary["quantile"] = series.quantile(config.summary["quantile"])

if config.summary.get("iqr"):
    summary["iqr"] = series.quantile(0.75) - series.quantile(0.25)

if config.summary.get("range"):
    summary["range"] = series.max() - series.min()

if config.summary.get("mad"):
    summary["mad"] = series.mad()

if config.summary.get("cv"):
    summary["cv"] = series.std() / series.mean()

if config.summary.get("n_zeros"):
    summary["n_zeros"] = (series == 0).sum()

if config.summary.get("n_missing"):
    summary["n_missing"] = series.isna().sum()

if config.summary.get("memory_size"):
    summary["memory_size"] = series.memory_usage()

if config.summary.get("monotonic_increase"):
    summary["monotonic_increase"] = series.is_monotonic_increasing

if config.summary.get("monotonic_decrease"):
    summary["monotonic_decrease"] = series.is_monotonic_decreasing

if config.summary.get("monotonic_increase_strict"):
    summary["monotonic_increase_strict"] = series.is_monotonic_increasing and (
        series.iloc[1:] >= series.iloc[:-1].values
