:param path_glob: String. The path or file URI to list files and directories from.
:return: String. Yields the paths of all files and directories in the given path.
"""
path = self.get_local_path(path_glob)
if os.path.isdir(path):
    for dirpath, dirnames, filenames in os.walk(path):
        for dirname in dirnames:
            yield self.get_file_uri(os.path.join(dirpath, dirname))
        for filename in filenames:
            yield self.get_file_uri(os.path.join(dirpath, filename))
else:
    yield path_glob

