"""This function takes an HRP (Human Readable Part), data, and a specification as input and computes a Bech32 string. It combines the data with a checksum generated and returns the Bech32 string.

:param hrp: String. The Human Readable Part of the Bech32 string.
:param data: List of integers. The data values to be encoded.
:param spec: String. The specification to be used for encoding.
:return: String. The computed Bech32 string.
"""
if not isinstance(data, list):
    raise TypeError("data must be a list")
if not isinstance(hrp, str):
    raise TypeError("hrp must be a string")
if not isinstance(spec, str):
    raise TypeError("spec must be a string")
if len(data) == 0:
    raise ValueError("data must contain at least one element")
if len(hrp) == 0:
    raise ValueError("hrp must not be empty")
if len(spec) == 0:
    raise ValueError("spec must not be empty")
if len(spec) > 20:
    raise ValueError("spec must not be longer than 20 characters")
if len(spec) < 1:
    raise ValueError("spec must not be shorter than 1 character")
if not re.match(r"^[a-z]+$", spec):
    raise ValueError("spec must be lowercase")
if not re.match(r"^[a-z]+$", hrp):
    raise ValueError("hrp must be lowercase")
if not all(isinstance(x, int) for x in data):
    raise TypeError("data must be a list of integers")
if not all(0 <= x <= 255 for x in data):
    raise ValueError("data must be a list of integers between 0 and 255")
if len(data) > 62:
    raise ValueError("data must not contain more than 62 elements")
if len(data) > 0 and data[0] > 29:
    raise ValueError("data must not contain elements greater than 29")
if len(data) > 1 and data[1] > 31:
    raise ValueError("data must not contain elements greater than 31")
if len(data) > 2 and data[2] > 33:
    raise ValueError("data must not contain elements greater than 33")
if len(data) > 3 and data[3] > 35:
    raise ValueError("data must not contain elements greater than 35")
if len(data) > 4 and data[4] > 37:
    raise ValueError("data must not contain elements greater than 37")
if len(data) > 5 and data[5] > 38:
    raise ValueError("data must not contain elements greater than 38")
if len(data) > 6 and data[6] > 39:
    raise ValueError("data must not contain elements greater than 39")
if len(data) > 7 and data[7] > 41:
    raise ValueError("data must not contain elements greater than 41")
if len(data) > 8 and data[8] > 43:
    raise ValueError("data must not contain elements greater than 43")
