"""This function adds a single revision to an existing revision map. It performs various operations such as adding the revision to the map, adding branches, mapping branch labels, adding dependencies, updating bases and real bases, checking and adding referenced revisions, normalizing dependencies, and updating real heads and heads.

:param self: RevisionMap. An instance of the RevisionMap class.
:param revision: Revision. The revision to be added to the map.
:param _replace: Bool. Whether to replace an existing revision with the same key. Defaults to False.
:return: No return values.
"""
if revision.revision in self._revision_map:
    if _replace:
        self._revision_map[revision.revision] = revision
    else:
        raise RevisionError(
            "Revision %s already exists. Use --force to override."
            % revision.revision
        )
else:
    self._revision_map[revision.revision] = revision

if revision.branch_labels:
    for branch_label in revision.branch_labels:
        if branch_label in self._revision_map.setdefault(
            "heads", {}
        ):  # type: ignore
            raise RevisionError(
                "Branch label %s is already used by %s"
                % (branch_label, self._revision_map["heads"][branch_label])
            )
        self._revision_map.setdefault("branches", {})[branch_label] = (
            revision.revision,
        )

if revision.dependencies:
    for dep in revision.dependencies:
        if dep not in self._revision_map:
            raise RevisionError(
                "Dependency %s not found.  "
                "Are you sure it's in the scripts directory?" % dep
            )
        if dep in self._revision_map.setdefault(
            "heads", {}
        ):  # type: ignore
            dep_revision = self._revision_map["heads"][dep]
        else:
            dep_revision = self._revision_map[dep]
        if dep_revision.revision not in revision._resolved_dependencies:
            revision._resolved_dependencies.add(dep_revision.revision)
            revision._dependencies.append(dep_revision)

if revision.merge_branch_labels:
    for branch_label in revision.merge_branch_labels:
        if branch_label not in self._revision_map.setdefault(
            "heads", {}
        ):  # type: ignore
            raise RevisionMapError(
                "Branch label %s does not exist.  "
                "Was the revision that introduced it "
                "removed from the script directory?" % branch_label
            )
        merge_branch_revision = self._revision_map["heads"][branch_label]
        if merge_branch_revision.revision not in revision._resolved_dependencies:
            revision._resolved_dependencies.add(merge_branch_revision.revision)
            revision._dependencies.append(merge_branch_revision)

if revision.branch_labels:
    self._revision_map.setdefault("heads", {})[
        revision.revision
    ] = revision  # type: ignore

if revision.revision != "head":
    self._revision_map.setdefault("heads", {})[
        "head"
    ] = self._revision_map[revision.revision]

if revision.revision != "base":
    self._revision_map.setdefault("heads", {})[
        "base"
    ] = self._revision_map[revision.revision]

if revision.dependencies:
    self._revision_map.setdefault("down_revisions", {})[
        revision.revision
    ] = revision.dependencies

if revision.merge_branch_labels:
    self._revision_map.setdefault("down_revisions", {})[
        revision.revision
    ] += revision.merge_branch_labels

if revision.revision != "base":
    self._revision_map.setdefault("down_revisions", {})[
        "base"
    ] += revision.merge_branch_labels

if revision.revision != "head":
    self._revision_map.setdefault("down_revisions", {})[
        "head"
    ] += revision.merge_branch_labels

if revision.revision != "head":
    self._revision_order.append(revision.revision)

if revision.revision != "base":
    self._revision_order.append(revision.revision)

if revision.revision != "head":
    self._revision_order.append(revision.revision)

"""This function parses an incoming bytestream as JSON and returns the resulting data. It decodes the stream using the specified encoding and parses the decoded stream into a Python object.

:param self: JSONParser. An instance of the JSONParser class.
:param stream: The bytestream to be parsed as JSON.
:param media_type: [optional] The media type of the stream. Defaults to None.
:param parser_context: [optional] Additional context for the parser. Defaults to None.
:return: The parsed data as a Python object.
"""
if not parser_context:
    parser_context = {}
encoding = parser_context.get("encoding", settings.DEFAULT_CHARSET)
parser_context["encoding"] = encoding

try:
    decoded_stream = stream.decode(encoding)
    return json.loads(decoded_stream, **self.decoder_kwargs)
except ValueError as exc:
    raise ParseError("JSON parse error - %s" % str(exc))

"""This function iterates through script revisions starting from the upper revision identifier and ending at the lower revision identifier. It uses the `down_revision` marker inside each migration script to determine the traversal order.

:param self: RevisionMap. An instance of the RevisionMap class.
:param upper: _RevisionIdentifierType. The upper revision identifier to start the iteration from.
:param lower: _RevisionIdentifierType. The lower revision identifier to end the iteration at.
:param implicit_base: Bool. Whether to include the implicit base revision in the iteration. Defaults to False.
:param inclusive: Bool. Whether to include the upper revision in the iteration. Defaults to False.
:param assert_relative_length: Bool. Whether to assert that the number of revisions between the upper and lower is the same as the number of revisions returned. Defaults to True.
:param select_for_downgrade: Bool. Whether to select revisions for downgrade instead of upgrade. Defaults to False.
:return: Iterator[Revision]. An iterator that yields `Revision` objects.
"""
if not isinstance(upper, list):
    upper = [upper]
if not isinstance(lower, list):
    lower = [lower]

upper_revs = self._get_revisions(upper)
lower_revs = self._get_revisions(lower)

if not lower_revs:
    raise util.CommandError(
        "No such revision(s): %s" % ", ".join(lower)
    )
if not upper_revs:
    raise util.CommandError(
        "No such revision(s): %s" % ", ".join(upper)
    )

upperrev = upper_revs[-1]
lowerrev = lower_revs[0]

if not lowerrev.down_revision and not implicit_base:
    raise util.CommandError(
        "No downgrade candidate for revision %s" % lowerrev.log_entry
    )

if inclusive:
    upperrev = upperrev.down_revision or upperrev

if not upperrev:
    raise util.CommandError(
        "No downgrade candidate for revision %s" % upperrev.log_entry
    )

if assert_relative_length:
    assert_rel_length = len(upper_revs) - len(lower_revs)
    if assert_rel_length != 0:
        raise util.CommandError(
            "Relative revision length does not match: expected %d, got %d"
            % (assert_rel_length, len(upper_revs) - len(lower_revs))
        )

if select_for_downgrade:
    revs = upper_revs
else:
    revs = lower_revs

for rev in revs:
    yield rev

if select_for_downgrade:
    revs = lower_revs
else:
    revs = upper_revs

for rev in revs:
    if rev.down_revision:
        yield rev.down_revision

"""This function takes format strings with anonymous positional arguments (e.g., "{}" and {:d}) and converts them into numbered ones for explicitness and compatibility with Python 2.6. It replaces the anonymous positional arguments with numbered ones and returns the modified string.

:param fstr: String. The format string with anonymous positional arguments.
:return: String. The modified format string with numbered positional arguments.
"""
if not fstr:
    return fstr

# If the format string is empty, we don't need to do anything.
fstr = to_unicode(fstr)
if len(fstr) == 0:
    return fstr

# If the format string is a simple string, we don't need to do anything.
if fstr.count("{") == 0:
    return fstr

# If the format string is a simple string with a single positional argument, we don't need to do anything.
if fstr.count("{") == 1:
    if fstr.count("}") == 1:
        return fstr

# If the format string is a simple string with a single named argument, we don't need to do anything.
if fstr.count("{") == 1:
