"""
if isinstance(output_file, str):
    if output_file.endswith(".html"):
        self.save_html(output_file, file_info)
    elif output_file.endswith(".json"):
        self.save_json(output_file, file_info)
    elif output_file.endswith(".gz"):
        self.save_json(output_file, file_info, gzip=True)
